head.script:
scwin.onpageload = function() {
    var tabOpt = {
        label: "test",
        closeable: true,
        openAction: "select"
    };
    var contOpt = {
        src: "tabControl_WPFF-106_(WSQ-3260)_sub.xml"
    };
    tabControl1.addTab("test1", tabOpt, contOpt);
};
scwin.onpageunload = function() {};
scwin.checkLog = function() {
    var log = WebSquare.logger.getLog();
    log = WebSquare.logger.getLog();
    return log.substring().indexOf("[ Cannot read property '0' of undefined ]") == "-1";
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_test1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
